// Extract ticket fields into clean variables for downstream nodes
const t = $input.first().json;
const props = t.properties || {};

const keyword = props.Keyword?.rich_text?.[0]?.plain_text
  || t.property_keyword || '';
const type = props.Type?.select?.name
  || t.property_type || 'Long-form blog';
const cluster = props.Cluster?.select?.name
  || t.property_cluster || '';
const icp = (props['ICP slice']?.multi_select || [])
  .map(s => s.name).join(', ')
  || (Array.isArray(t.property_icp_slice) ? t.property_icp_slice.join(', ') : t.property_icp_slice || '');
const notes = props['Notes for AI']?.rich_text?.map(r => r.plain_text).join('')
  || t.property_notes_for_ai || '';

return [{
  json: {
    ticket_id: t.id,
    keyword,
    type,
    cluster,
    icp_slice: icp,
    notes_for_ai: notes,
    page_url: t.url
  }
}];

const brandBlocks = $('Get many child blocks').all();

function blockToMd(j) {
  if (!j || !j.type) return '';
  var typeKey = j.type;
  var blockData = j[typeKey];
  if (!blockData) return '';
  var rt = blockData.text || blockData.rich_text;
  if (!Array.isArray(rt) || rt.length === 0) return '';
  var text = rt.map(function(r) { return r.plain_text || ''; }).join('');
  if (!text) return '';
  if (typeKey === 'heading_1') return '# ' + text;
  if (typeKey === 'heading_2') return '## ' + text;
  if (typeKey === 'heading_3') return '### ' + text;
  if (typeKey === 'bulleted_list_item') return '- ' + text;
  if (typeKey === 'numbered_list_item') return '1. ' + text;
  if (typeKey === 'callout') return '> ' + text;
  if (typeKey === 'quote') return '> ' + text;
  if (typeKey === 'toggle') return '> ' + text;
  if (typeKey === 'code') return text;
  return text;
}

const brandMd = brandBlocks
  .map(function(b) { return blockToMd(b.json); })
  .filter(function(s) { return s && s.length > 0; })
  .join('\n\n');

const ticket = $('Extract').first().json;

// Brand Context block — cacheable (static across all tickets)
const brandContextText = '----- BRAND CONTEXT -----\n\n' + brandMd;

// Ticket-specific block — changes every call
const ticketTaskText = '----- TICKET -----\n\n'
  + 'Keyword: ' + (ticket.keyword || '(no keyword)')
  + '\nType: ' + (ticket.type || 'Long-form blog')
  + '\nCluster: ' + (ticket.cluster || '-')
  + '\nICP slice: ' + (ticket.icp_slice || '-')
  + '\nNotes for AI: ' + (ticket.notes_for_ai || '-')
  + '\n\n----- TASK -----\n\n'
  + 'Write one piece of content matching the Type and Brand Context section 9 format spec. '
  + 'Output a single JSON object with these fields: title, slug, meta_title (max 60 chars), '
  + 'meta_description (max 155 chars), body_markdown, body_html, tags, faq, '
  + 'internal_links_suggested, schema_org_type, word_count. No prose outside the JSON.';

const systemPrompt = 'You are the content engine for the brand in the user message. '
  + 'Always respond with one JSON object matching the schema. '
  + 'Never output prose outside the JSON. '
  + 'Follow Brand Context voice and never-say rules strictly.';

// Brand Context goes in user message as content block with cache_control
// (System field stays as string to avoid n8n / API edge cases)
const body = {
  model: 'claude-sonnet-4-6',
  max_tokens: 8000,
  system: systemPrompt,
  messages: [{
    role: 'user',
    content: [
      {
        type: 'text',
        text: brandContextText,
        cache_control: { type: 'ephemeral' }
      },
      {
        type: 'text',
        text: ticketTaskText
      }
    ]
  }]
};

return [{
  json: {
    ticket_id: ticket.ticket_id,
    keyword: ticket.keyword || '',
    type: ticket.type || '',
    brand_context_block_count: brandBlocks.length,
    brand_context_md_length: brandMd.length,
    brand_context_md: brandMd,
    claude_request_body: JSON.stringify(body)
  }
}];

// Robust parser with debug fallback
const resp = $input.first().json;
const text = resp.content && resp.content[0] && resp.content[0].text;

if (!text) {
  throw new Error('Claude response missing text');
}

// Clean common issues
let cleaned = text.trim();
// Strip markdown fences like ```json ... ```
cleaned = cleaned.replace(/^```(?:json)?\s*/i, '');
cleaned = cleaned.replace(/\s*```\s*$/, '');

let draft = null;
let parseError = null;

try {
  draft = JSON.parse(cleaned);
} catch (e) {
  parseError = e.message;
  // Try extracting first balanced JSON object
  var match = cleaned.match(/\{[\s\S]*\}/);
  if (match) {
    try {
      draft = JSON.parse(match[0]);
      parseError = null;
    } catch (e2) {
      parseError = e2.message;
    }
  }
}

// If parsing failed, return debug info instead of crashing
if (!draft) {
  return [{
    json: {
      PARSE_FAILED: true,
      error: parseError,
      raw_length: cleaned.length,
      raw_first_500: cleaned.substring(0, 500),
      raw_last_500: cleaned.substring(Math.max(0, cleaned.length - 500))
    }
  }];
}

// Success path
const meta = $('Build Draft Code').first().json;

return [{
  json: {
    PARSE_FAILED: false,
    ticket_id: meta.ticket_id,
    keyword: meta.keyword,
    title: draft.title || '',
    slug: draft.slug || '',
    meta_title: draft.meta_title || '',
    meta_description: draft.meta_description || '',
    body_markdown: draft.body_markdown || '',
    body_html: draft.body_html || '',
    word_count: draft.word_count || 0,
    tags: Array.isArray(draft.tags) ? draft.tags : [],
    faq: Array.isArray(draft.faq) ? draft.faq : [],
    internal_links_suggested: Array.isArray(draft.internal_links_suggested) ? draft.internal_links_suggested : [],
    schema_org_type: draft.schema_org_type || 'Article'
  }
}];

// Build Google Doc Content
// Takes parsed Claude draft + resolves ticket_id from upstream Notion node
// Outputs: { ticket_id, title, doc_title, doc_content_text }

const draft = $input.first().json || {};

// Resolve ticket_id (fallback chain across upstream nodes)
let ticketId = null;
const sources = [
  function() { return $('Get many database pages').first().json.id; },
  function() { return $('Extract').first().json.ticket_id; },
  function() { return $('Extract').first().json.id; },
  function() { return draft.ticket_id; },
  function() { return $('Parse Response').first().json.ticket_id; },
  function() { return $('Build Draft Code').first().json.ticket_id; }
];

for (var i = 0; i < sources.length; i++) {
  try {
    var v = sources[i]();
    if (v && typeof v === 'string' && v.length >= 32) {
      ticketId = v;
      break;
    }
  } catch (e) {}
}

if (!ticketId) {
  throw new Error('Cannot resolve ticket_id from upstream nodes.');
}

const title = draft.title || 'Untitled Draft';
const md = draft.body_markdown || '';

// Build a single text blob for the Google Doc
var docText = '';

docText += title + '\n\n';

docText += 'Meta title: ' + (draft.meta_title || '-') + '\n';
docText += 'Meta description: ' + (draft.meta_description || '-') + '\n';
docText += 'Word count: ' + (draft.word_count || 0) + '\n';
docText += 'Schema.org type: ' + (draft.schema_org_type || 'Article') + '\n';
docText += '\n----------\n\n';

docText += md + '\n';

if (Array.isArray(draft.faq) && draft.faq.length > 0) {
  docText += '\n----------\n\nFAQ\n\n';
  draft.faq.forEach(function(qa) {
    if (qa && qa.q) {
      docText += 'Q: ' + qa.q + '\n';
      if (qa.a) docText += 'A: ' + qa.a + '\n';
      docText += '\n';
    }
  });
}

return [{
  json: {
    ticket_id: ticketId,
    title: title,
    doc_title: title + ' — ' + new Date().toISOString().slice(0, 10),
    doc_content_text: docText
  }
}];

